/// </summary>
public sealed class LayerDependencyTests
{
    private static readonly ArchUnitNET.Domain.Architecture Architecture = new ArchLoader()
        .LoadAssemblies(
            typeof(Domain.Money).Assembly,
            typeof(Application.AuthorizePayment).Assembly,
            typeof(Infrastructure.HttpPaymentGateway).Assembly)
        .Build();

    private static readonly IObjectProvider<IType> DomainLayer =
        Types().That().ResideInNamespace("PaymentAuthorization.Domain").As("Domain");

    private static readonly IObjectProvider<IType> ApplicationLayer =
        Types().That().ResideInNamespace("PaymentAuthorization.Application").As("Application");

    [Fact]
    public void Domain_depends_on_nothing_but_the_language_core()
    {
        IArchRule rule = Types().That().Are(DomainLayer)
            .Should().OnlyDependOn(DomainLayer)
            .Because("the Domain layer must have zero knowledge of Application or Infrastructure concerns.");

        rule.Check(Architecture);
    }

    [Fact]
    public void Application_depends_only_on_domain_and_itself()
    {
        IArchRule rule = Types().That().Are(ApplicationLayer)
            .Should().OnlyDependOn(ApplicationLayer.Or(DomainLayer))
