using ArchUnitNET.Domain;
using ArchUnitNET.Fluent;
using ArchUnitNET.Loader;
using ArchUnitNET.xUnit;
using static ArchUnitNET.Fluent.ArchRuleDefinition;

namespace PaymentAuthorization.IntegrationTest.Architecture;

/// <summary>
/// Guards the Clean Architecture boundaries so a technical detail can never sneak into
/// business code again: Domain must stay pure and Application may only see Domain.
/// </summary>
public sealed class LayerDependencyTests
{
    private static readonly ArchUnitNET.Domain.Architecture Architecture = new ArchLoader()
        .LoadAssembliesIncludingDependencies(
            typeof(Domain.Money).Assembly,
            typeof(Application.AuthorizePayment).Assembly,
            typeof(Infrastructure.HttpPaymentGateway).Assembly },
            true)
        .Build();

    private const string DomainNamespace = "PaymentAuthorization.Domain";
    private const string ApplicationNamespace = "PaymentAuthorization.Application";

    private static readonly IObjectProvider<IType> DomainLayer =
        Types().That().ResideInNamespace(DomainNamespace).As("Domain");

    private static readonly IObjectProvider<IType> ApplicationLayer =
        Types().That().ResideInNamespace(ApplicationNamespace).As("Application");

    private static readonly IObjectProvider<IType> ApplicationOrDomainLayer =
        Types().That().ResideInNamespace(ApplicationNamespace).Or().ResideInNamespace(DomainNamespace)
            .As("Application or Domain");

    [Fact]
    public void Domain_depends_on_nothing_but_the_language_core()
    {
        IArchRule rule = Types().That().Are(DomainLayer)
            .Should().OnlyDependOn(DomainLayer)
            .Because("the Domain layer must have zero knowledge of Application or Infrastructure concerns.");

        rule.Check(Architecture);
    }

    [Fact]
    public void Application_depends_only_on_domain_and_itself()
    {
        IArchRule rule = Types().That().Are(ApplicationLayer)
            .Should().OnlyDependOn(ApplicationOrDomainLayer)
            .Because("the Application layer may orchestrate Domain objects but must never reach into Infrastructure.");

        rule.Check(Architecture);
    }
}
